    /**
     * Method to retrieve the Cart via CartFetchOneSummary
     * @param 	summary CartFetchOneSummary 
     * @return 	CartFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Cart getCart( CartFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "CartFetchOneSummary arg cannot be null" );
    	
    	Cart entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Cart
        	// --------------------------------------
        	CompletableFuture<Cart> futureEntity = queryGateway.query(new FindCartQuery( new LoadCartFilter( summary.getCartId() ) ), ResponseTypes.instanceOf(Cart.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Cart with id " + summary.getCartId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


