    public List<Cart> getAllCart() 
    throws ProcessingException {
        List<Cart> list = null;

        try {
        	CompletableFuture<List<Cart>> futureList = queryGateway.query(new FindAllCartQuery(), ResponseTypes.multipleInstancesOf(Cart.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Cart";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

